style.css:
/* i really want this to be global */

/* Ultrakill 7-4 Earthmover Background */
body,
html {
    background: url('https://i.imgur.com/b7GVzPv.jpeg') center/cover no-repeat fixed !important;
}

/* THIS is the key fix — make the main content wrapper transparent */
#container-main,
#main,
.rbx-page {
    background: transparent !important;
    background-color: transparent !important;
}

/* Header */
.rbx-header,
.rbx-portal-header {
    background-color: rgba(10, 10, 10, 0.85) !important;
    border-bottom: 1px solid #8b0000 !important;
}

/* Cards */
.rbx-portal-card,
.rbx-feed-card {
    background-color: rgba(15, 15, 15, 0.8) !important;
    border: 1px solid rgba(139, 0, 0, 0.4) !important;
}
